export const BODY: string = "\n<p>تصویر کے کونے گول کرنے میں صرف چند منٹ لگتے ہیں۔ آپ تصویر اپ لوڈ کرتے ہیں، منحنی طے کرنے کے لیے سلائیڈر گھسیٹتے ہیں، اور نرم شدہ نتیجہ ڈاؤن لوڈ کرتے ہیں۔</p>\n<p>یہ طریقہ پورا عمل قدم بہ قدم بتاتا ہے۔ اس میں رداس سلائیڈر، فی کونہ کنٹرول، مکمل دائرہ شارٹ کٹ، بھرنے کے انتخاب، اور وہ برآمد فارمیٹ شامل ہیں جو کونے شفاف رکھتے ہیں۔</p>\n<p>آخر تک آپ کسی بھی آلے پر گول اوتار، کارڈ تصویر، یا گولی شکل والا بینر بنا سکیں گے۔ نتیجہ جانچنے تک اصل تصویر رکھیں۔</p>\n<h2 id=\"before-you-start\">شروع کرنے سے پہلے: شکل چنیں</h2>\n<p>ٹول کھولنے سے پہلے طے کریں کہ آپ کو کون سی شکل چاہیے۔ دائرہ اوتار کو سوٹ کرتا ہے، ہلکی گولائی کارڈ کو سوٹ کرتی ہے، اور گولی بینر یا بیج کو سوٹ کرتی ہے۔</p>\n<p>منزل بھی جانچیں۔ پروفائل سلاٹ دائرہ مانگ سکتا ہے، جبکہ بلاگ کارڈ کو صرف اوپر والے دو کونے گول چاہییں ہو سکتے ہیں۔</p>\n<p>اصل تصویر استعمال کریں، کمپریس شدہ کاپی نہیں۔ تیز اصل سے گول کرنے سے خمیدہ کنارے ہموار رہتے ہیں، جبکہ نرم کاپی کو گول کرنے سے منحنی کھردرے لگتے ہیں۔</p>\n<h2 id=\"step-by-step\">پانچ مراحل میں تصویر کے کونے گول کریں</h2>\n<p>عمل ہلکی گولائی اور مکمل دائرے کے لیے ایک جیسا ہے۔ اپ لوڈ کریں، رداس طے کریں، بھرنا چنیں، پیش نظارہ جانچیں، اور ڈاؤن لوڈ کریں۔</p>\n<p>رداس پر وقت لگائیں۔ قیمت میں چھوٹی تبدیلی شکل کے احساس میں بڑا فرق ڈال سکتی ہے، اس لیے گھسیٹتے ہوئے پیش نظارہ دیکھیں۔</p>\n<ol>\n<li>اپنی تصویر ڈراپ زون میں گھسیٹ کر، اپنے آلے سے چن کر، یا Ctrl+V سے اسکرین شاٹ چسپاں کر کے اپ لوڈ کریں۔</li>\n<li>منحنی طے کرنے کے لیے All Corners Radius سلائیڈر گھسیٹیں، ایڈجسٹ کرتے ہوئے براہ راست پکسل پڑھنے کو دیکھیں۔</li>\n<li>مختلف رداس طے کرنے کے لیے فی کونہ موڈ آن کریں، یا گول یا گولی شکل کے لیے Full Circle / Pill شارٹ کٹ استعمال کریں۔</li>\n<li>دیکھنے والے کونوں کے لیے Outer Corner Fill کے نیچے Transparent چنیں، یا بھرے پس منظر کے لیے Solid Color چنیں۔</li>\n<li>برآمد فارمیٹ چنیں، شفافیت رکھنے کے لیے PNG یا WebP، پھر نتیجہ محفوظ کرنے کے لیے Download پر کلک کریں۔</li>\n</ol>\n<p>استعمال سے پہلے ڈاؤن لوڈ شدہ فائل ایک بار کھولیں۔ تصدیق کریں کہ کونے ہموار لگتے ہیں اور کوئی اہم چیز کٹ نہیں گئی۔</p>\n<h2 id=\"setting-radius\">کونے کا رداس طے کرنا</h2>\n<p>رداس سلائیڈر کنٹرول کرتا ہے کہ کونے کتنے گول ہیں۔ چھوٹی قیمت ہلکی نرمی دیتی ہے، جبکہ بڑی قیمت کونوں کو گہرے منحنی میں بدل دیتی ہے۔</p>\n<p>10 سے 20 پکسل رداس کارڈ، تھمب نیل اور اسکرین شاٹ کو سوٹ کرتا ہے۔ گولائی ہلکی ہے، اور تصویر پھر بھی نرم کناروں والا مستطیل لگتی ہے۔</p>\n<p>50 سے 100 پکسل رداس واضح گول شکل دیتا ہے۔ یہ اوتار، سوشل پوسٹ اور ایپ گرافکس کو سوٹ کرتا ہے، جہاں شکل ڈیزائن کا حصہ ہے۔</p>\n<h2 id=\"per-corner-mode\">فی کونہ موڈ استعمال کرنا</h2>\n<p>فی کونہ موڈ آپ کو ہر کونے کے لیے مختلف رداس طے کرنے دیتا ہے۔ اسے آن کریں، اور چار الگ سلائیڈر دکھائی دیتے ہیں، تصویر کے ہر کونے کے لیے ایک۔</p>\n<p>بلاگ کارڈ کلاسک استعمال ہے۔ اوپر والے دو کونے گول کریں اور نیچے والے دو مربع چھوڑ دیں، تاکہ تصویر کارڈ کے اوپر صاف بیٹھے۔</p>\n<p>فی کونہ موڈ بند کرنے سے تمام کونوں کے لیے ایک رداس واپس آ جاتا ہے۔ انفرادی قیمتیں موڈ بند ہونے کے دوران محفوظ رہتی ہیں، اس لیے آپ انہیں کھوئے بغیر واپس جا سکتے ہیں۔</p>\n<h2 id=\"full-circle-shortcut\">مکمل دائرہ / گولی شارٹ کٹ استعمال کرنا</h2>\n<p>Full Circle شارٹ کٹ ایک کلک میں رداس کو تصویر سائز کا آدھا طے کرتا ہے۔ مربع تصویر پر یہ مکمل دائرہ بناتا ہے، اور مستطیل پر یہ گولی شکل بناتا ہے۔</p>\n<p>صاف دائرے کے لیے پہلے تصویر کو 1:1 کراپ کریں۔ شارٹ کٹ والا مربع ماخذ مکمل گول اوتار دیتا ہے جو کسی بھی پروفائل سلاٹ میں فٹ ہوتا ہے۔</p>\n<p>مستطیل تصویر پر شارٹ کٹ گولی بناتا ہے: مکمل گول سروں والا مستطیل۔ گولیاں بٹن، بیج اور بینر کو سوٹ کرتی ہیں۔</p>\n<h2 id=\"choosing-fill\">شفاف یا ٹھوس بھرنا چننا</h2>\n<p>جب کونے کٹ جاتے ہیں تو خالی جگہ بھرنی چاہیے۔ شفاف کونوں کو دیکھنے والا چھوڑتا ہے، جبکہ ٹھوس انہیں رنگ سے بھرتا ہے۔</p>\n<p>ویب گرافکس، اوتار اور اوورلے کے لیے شفاف چنیں۔ تصویر کسی بھی پس منظر کے ساتھ مل جاتی ہے، کیونکہ کونے تصویر کے پیچھے جو کچھ ہے، وہ دکھاتے ہیں۔</p>\n<p>ٹھوس چنیں جب منزل شفافیت سنبھال نہیں سکتی۔ سفید ٹھوس بھرنا تصویر کو سفید کارڈ پر گول تصویر جیسا دکھاتا ہے، جو دستاویزات اور پرنٹ کو سوٹ کرتا ہے۔</p>\n<h2 id=\"choosing-format\">برآمد فارمیٹ چننا</h2>\n<p>شفافیت کے ساتھ تیز ترین نتیجے کے لیے PNG چنیں۔ یہ بغیر نقصان کا ہے، اس لیے خمیدہ کنارے ہموار رہتے ہیں، اور یہ ہر جگہ کام کرتا ہے، بشمول پرانے براؤزر۔</p>\n<p>جب آپ شفافیت کے ساتھ چھوٹی فائلیں چاہیں تو WebP چنیں۔ یہ PNG سے چھوٹی فائلیں دیتا ہے انہی دیکھنے والے کونوں کے ساتھ، اگرچہ چند پرانے نظام اسے مسترد کرتے ہیں۔</p>\n<p>JPG صرف تب چنیں جب کونوں میں ٹھوس بھرنا ہو۔ JPG میں شفافیت نہیں، اس لیے JPG کے طور پر شفاف برآمد کو ٹھوس بھرنا ملتا ہے، جو آپ کے پس منظر سے میل نہ کھائے۔</p>\n<h2 id=\"previewing\">ڈاؤن لوڈ سے پہلے پیش نظارہ دیکھنا</h2>\n<p>ڈاؤن لوڈ سے پہلے ہمیشہ پیش نظارہ دیکھیں۔ جانچیں کہ کونے ہموار ہیں، رداس درست لگتا ہے، اور کوئی اہم چیز کٹ نہیں گئی۔</p>\n<p>کسی کونے میں زوم کریں اور منحنی دیکھیں۔ ہموار قوس کا مطلب ہے گولائی اچھی طرح کام کی، جبکہ ناہموار کنارہ کا مطلب ہے ماخذ بہت چھوٹا یا بہت نرم تھا۔</p>\n<p>بھرنا اس پس منظر پر جانچیں جہاں تصویر رہے گی۔ شفاف کونہ کہیں بھی درست لگتا ہے، جبکہ ٹھوس بھرنا صرف اس رنگ سے میل کھاتا ہے جس پر وہ طے تھا۔</p>\n<h2 id=\"rounding-for-avatar\">اوتار کے لیے کونے گول کرنا</h2>\n<p>پہلے <a href=\"/ur/tasveer-crop-karein/\">Image Cropper</a> سے تصویر کو مربع کراپ کریں۔ چہرہ مرکز میں والی 1:1 کراپ گول اوتار کے لیے بہترین نقطہ آغاز دیتی ہے۔</p>\n<p>مربع تصویر اپ لوڈ کریں اور Full Circle شارٹ کٹ کلک کریں۔ رداس تصویر سائز کا آدھا ہو جاتا ہے، اور تصویر مکمل دائرہ بن جاتی ہے۔</p>\n<p>چہرہ فریم کے اندر اچھی طرح رکھیں۔ کونے کٹ جاتے ہیں، اس لیے کنارے کے قریب چہرہ منحنی سے کان یا بالوں کا حصہ کھو سکتا ہے۔</p>\n<h2 id=\"rounding-for-cards\">کارڈ اور UI کے لیے کونے گول کرنا</h2>\n<p>تصویر رداس کو کارڈ رداس سے ملائیں۔ 16 پکسل رداس والے کارڈ کے اندر 16 پکسل رداس والی تصویر ہموار لگتی ہے، جبکہ بے میل رداس لاپرواہ لگتے ہیں۔</p>\n<p>بلاگ کارڈ کے لیے اوپر والے دو کونے گول کریں اور نیچے والے دو مربع چھوڑ دیں۔ فی کونہ موڈ آن کریں، اوپر والے رداس طے کریں، اور نیچے والے صفر پر چھوڑ دیں۔</p>\n<p>سیٹ کے تمام کارڈ میں رداس مستقل رکھیں۔ میل کھانے والے کونوں والا کارڈ گرڈ پیشہ ورانہ لگتا ہے، جبکہ ملے جلے رداس بے ترتیب لگتے ہیں۔</p>\n<h2 id=\"rounding-screenshots\">اسکرین شاٹ پر کونے گول کرنا</h2>\n<p>محفوظ کرنے والا مرحلہ چھوڑنے کے لیے اسکرین شاٹ Ctrl+V سے سیدھا چسپاں کریں۔ تصویر فوراً ٹول میں دکھائی دیتی ہے، گول کرنے کے لیے تیار۔</p>\n<p>اسکرین شاٹ کے لیے 10 سے 20 پکسل کا چھوٹا رداس استعمال کریں۔ ہلکی گولائی کیپچر کو جدید ایپ کارڈ جیسا دکھاتی ہے بغیر کوئی مواد چھپائے۔</p>\n<p>گول شدہ اسکرین شاٹ PNG کے طور پر برآمد کریں۔ بغیر نقصان کا فارمیٹ چھوٹا متن تیز رکھتا ہے، جو اہم ہے جب اسکرین شاٹ ترتیب یا غلطی کا پیغام دکھاتا ہے۔</p>\n<h2 id=\"rounding-on-mobile\">فون یا ٹیبلٹ پر کونے گول کرنا</h2>\n<p>ٹول ٹچ اسکرین پر کام کرتا ہے، اس لیے آپ تصویر اسی فون پر گول کر سکتے ہیں جس نے وہ لی تھی۔ اپنی گیلری سے اپ لوڈ کریں، رداس سلائیڈر گھسیٹیں، اور نتیجہ ڈاؤن لوڈ کریں۔</p>\n<p>چھوٹی اسکرین پر اوتار کے لیے Full Circle شارٹ کٹ استعمال کریں۔ ایک ٹیپ مربع تصویر کو دائرے میں بدل دیتی ہے، جو سلائیڈر کو بالکل قیمت تک گھسیٹنے سے تیز ہے۔</p>\n<p>ڈاؤن لوڈ سے پہلے پیش نظارہ مکمل سائز پر جانچیں۔ چھوٹی فون اسکرین پر ہلکا لگنے والا رداس کمپیوٹر پر دیکھنے پر زیادہ واضح ہو سکتا ہے۔</p>\n<h2 id=\"troubleshooting\">عام گولائی مسائل کا حل</h2>\n<p>اگر کونے شفافیت کی بجائے سفید پس منظر دکھائیں تو برآمد فارمیٹ جانچیں۔ JPG میں شفافیت نہیں، اس لیے کونے دیکھنے والے رکھنے کے لیے PNG یا WebP کے طور پر برآمد کریں۔</p>\n<p>اگر شکل دائرے کی بجائے گولی ہے تو ماخذ تصویر مستطیل ہے۔ پہلے اسے مربع کراپ کریں، پھر Full Circle شارٹ کٹ لگائیں۔</p>\n<p>اگر کونے ناہموار لگیں تو ماخذ تصویر شاید بہت چھوٹی ہے۔ اعلیٰ ریزولوشن اصل سے شروع کریں، اور منحنی ہموار رینڈر ہوں گے۔</p>\n<h2 id=\"combining-with-border\">گول کونوں کو سرحد کے ساتھ جوڑنا</h2>\n<p>پہلے کونے گول کریں، پھر <a href=\"/ur/tasveer-par-border-lagayein/\">Image Border Generator</a> سے سرحد شامل کریں۔ سرحد ٹول تصویر کی شکل پڑھتا ہے، اس لیے پہلے گول کرنے سے فریم سیدھا رہتا ہے۔</p>\n<p>سرحد رداس کو کونے رداس سے ملائیں۔ 16 پکسل رداس والی تصویر کے گرد 16 پکسل رداس والی سرحد ہموار لگتی ہے۔</p>\n<p>کارڈ شکل کے لیے پتلی سرحد ہلکے رداس کے ساتھ استعمال کریں۔ جوڑ جدید ایپ کارڈ جیسا لگتا ہے، جو سوشل پوسٹ اور پریزنٹیشن کو سوٹ کرتا ہے۔</p>\n<h2 id=\"quick-tips\">بہتر گول کونوں کے لیے فوری نکات</h2>\n<p>گول کرنے سے پہلے درست شکل پر کراپ کریں۔ دائرے کے لیے مربع کراپ، گولی کے لیے چوڑا کراپ، اور بلاگ تصویر کے لیے کارڈ کراپ، سب کراپر سے شروع ہوتے ہیں۔</p>\n<p>ڈاؤن لوڈ سے پہلے مکمل سائز پر پیش نظارہ دیکھیں۔ کونوں میں زوم کریں اور تصدیق کریں کہ منحنی ہموار ہیں اور کوئی اہم چیز کٹ نہیں گئی۔</p>\n<p>گول شدہ فائل کو واضح نام سے محفوظ کریں، جیسے avatar-circle.png۔ آپ کو وہی شکل دوبارہ چاہیے ہو سکتی ہے، اور واضح نام آپ کو کام دوبارہ کرنے سے بچاتا ہے۔</p>\n<h2 id=\"rounding-for-social-post\">سوشل پوسٹ کے لیے کونے گول کرنا</h2>\n<p>گول کونوں والی سوشل پوسٹ جدید اور دوستانہ لگتی ہے۔ نرم کنارے اس کے گرد ایپ کے کارڈ اور بٹن سے میل کھاتے ہیں، اس لیے تصویر انٹرفیس کے ساتھ مل جاتی ہے۔</p>\n<p>فیڈ پوسٹ کے لیے چھوٹا سے درمیانہ رداس استعمال کریں۔ 10 سے 20 پکسل کی ہلکی گولائی تصویر کو نرم کرتی ہے بغیر اس کی شخصیت بدلے یا کوئی مواد چھپائے۔</p>\n<p>اپنی پوسٹوں میں رداس مستقل رکھیں۔ فیڈ جہاں ہر تصویر ایک ہی کونے شکل شیئر کرتی ہے، منتخب لگتی ہے، جبکہ ملے جلے رداس بے ترتیب لگتے ہیں۔</p>\n<h2 id=\"rounding-for-presentation\">پریزنٹیشن کے لیے کونے گول کرنا</h2>\n<p>سلائیڈوں پر تصویریں گول کونوں کے ساتھ بہتر لگتی ہیں۔ نرم کنارے جدید سلائیڈ ڈیزائن سے میل کھاتے ہیں، اور تصویر چسپاں شدہ مستطیل کی بجائے جان بوجھ کر بنایا عنصر لگتی ہے۔</p>\n<p>تصویر رداس کو سلائیڈ تھیم سے ملائیں۔ 16 پکسل کارڈ کونوں والے ڈیک کو 16 پکسل رداس والی تصویریں چاہییں، تاکہ تصویریں اور کارڈ سیدھے ہوں۔</p>\n<p>بڑی پروجیکٹ ہونے والی سلائیڈوں کے لیے رداس چھوٹا رکھیں۔ بڑی اسکرین پر بڑا رداس تصویر پر غالب آ سکتا ہے، جبکہ ہلکی گولائی کسی بھی سائز پر ہلکی رہتی ہے۔</p>\n<p>موازنہ کے لیے <a href=\"/ur/blog/gol-kone-vs-circle-crop/\">Rounded Corners vs Circle Crop: Avatars and Cards</a> پڑھیں۔ مکمل جائزے کے لیے <a href=\"/ur/blog/tasveer-kone-gol-karein-rehnumai/\">Round Image Corners: Complete Guide</a> دیکھیں، اور گول تصویر کو فریم کرنے کے لیے <a href=\"/ur/tasveer-par-border-lagayein/\">Image Border Generator</a> آزمائیں۔</p>\n";

